import generated from '../demoHeights.json'

// per-site chrome config consumed by the shared Shell layout
export const componentLabel = 'Linear Genome View'
export const mainMaxWidth = '1400px'
export const demoFillHeight = false

// The example the landing page runs live, which takes that example's own
// reserved height rather than a second entry that could drift away from it.
export const landingDemo = 'with-init'

// Generated by `pnpm measure-demo-heights`, which loads every built page and
// measures what its demo settles at, at two widths, keeping the taller.
// Don't hand-edit it.
//
// Every demo here is a `client:only` island, and Astro gives an island
// `display: contents`, so until React hydrates its box is empty and 0 high with
// several hundred KB of engine still to fetch — and everything below it drops
// when the demo finally lands. Reserving the settled height on that box is what
// stops that, and it is also what earns the box its loading skeleton, which is
// styled on the island's empty state.
//
// Reserve the **tallest** the demo gets: too small still jumps the page, while
// too large only leaves space inside the demo's own border, so the generator
// measures narrow as well as wide. A demo whose height depends on its data
// rather than its config can't be pinned this way — it simply gets no entry,
// and falls back to today's behaviour of no reservation.
//
// Widened from the generated literal type on purpose: the templates look these
// up by a slug only known to be a string, and a slug with no entry should read
// as `undefined` rather than fail to compile.
export const demoHeights: Record<string, number> = generated
